// src/lib/katalog/marken/nachtmann.js – Nachtmann (Nachtmann Kristallglas, Teil der Riedel-Gruppe)
// Inhaber-Entscheidung Nr. 34 (31.10.2026): Nachtmann wie Riedel aufnehmen –
// Accessoire-Welt, ganzes Sortiment laut offiziellem Shop der Riedel-Gruppe
// Österreich (https://www.riedel.com/de-at, dort verkauft), Preise = Endpreise
// dieses Shops inkl. MwSt. je Variante, Stand 31.10.2026.
// KEIN Händlersatz (dealer: false): die Händleraussage für Nachtmann ist noch
// nicht bestätigt → Marke steht NICHT im Claim-Register (src/lib/legal/claims.js).
//
// Quelle der Produktliste: Produkt-Sitemap des AT-Shops (robots.txt →
// https://www.riedel.com/de-at/sitemap.xml → product.xml.gz), alle URLs
// „/de-at/nachtmann-…“. Normale HTTP-Abrufe der öffentlichen Produktseiten (kein
// gefälschter User-Agent, keine Umgehung), Daten aus der Seite selbst
// (Eigenschaften-Tabelle, angezeigter Preis, „SKU“, schema.org-Daten).
// Vollständigkeits-Check: qa-screenshots/wellness/produkte/vollstaendigkeit-nachtmann.md.
//
// Zusammenfassung (ANLEITUNG §3): ein Eintrag je Glasform/Artikel einer
// Kollektion; Packungsgrößen und Farben derselben Form (gleiche Bezeichnung,
// Kollektion und Höhe bzw. vom Shop als Variante verknüpft) sind Varianten mit
// eigenem Preis und eigener SKU. Varianten, die der Shop in seinen Daten nennt,
// deren Seite aber „nicht gefunden“ (HTTP 404) meldet, sind nicht erfasst.
// Shop-Felder je Variante: sku = „SKU“ der Produktseite, zerbrechlich = true
// (alles Kristallglas bzw. Bleikristall). Gewichte/Versandmaße nennt der Shop nicht.
// Bilder: je Produkt das Packshot-Foto der Produktseite (cdn.riedel.com),
// Motiv unverändert (typ "freisteller"; Dateien einheitlich ≤ 1600 px lange Kante, WebP q82 (tools/images/optimize-katalog.mjs)); dazu bis zu 2 Stimmungsbilder
// („lifestyle“) in der Fassung, die die Produktseite selbst lädt (srcset
// width=1920, WebP; typ "ambiente", bzw. "freisteller" bei hellem Studiogrund).
// Quelle je Bild in docs/bildquellen/QUELLEN.md.
// Zubehör: Poliertuch, Reinigungsperlen, Gläsertasche aus dem Riedel-Sortiment
// desselben Shops (Slugs aus riedel.js).
//
// Bewusst NICHT übernommen: Herstellertexte und Werbeaussagen (Kurztexte sind
// eigene Sätze aus den Eigenschaften der Produktseite)
// sowie den Kollektionsnamen „Noblesse“ in der Inhaltsangabe der Whisky-Sets
// Ethno/Punk (dort offensichtlich vom Noblesse-Set übernommen).

const MARKE_SLUG = "nachtmann";
const MARKE_NAME = "Nachtmann";

const STAND = "2026-10-31";
const T = (de, en, fr, it) => Object.freeze({ de, en, fr, it });
const mass = (key, wert) => Object.freeze({ key, wert });

// ---------------------------------------------------------------- Vokabular
const TYP = {
  Stielglas: T("Stielglas", "Stemmed glass", "Verre à pied", "Calice"),
  "Stielloses Glas": T("Glas ohne Stiel", "Stemless glass", "Verre sans pied", "Bicchiere senza stelo"),
  Becher: T("Becherglas", "Tumbler", "Gobelet", "Tumbler"),
  Glas: T("Glas", "Glass", "Verre", "Bicchiere"),
  Karaffe: T("Karaffe", "Carafe", "Carafe", "Caraffa"),
  Set: T("Whisky-Set", "Whisky set", "Coffret whisky", "Set whisky"),
  Platte: T("Platte", "Platter", "Plat", "Piatto da portata"),
  Teller: T("Teller", "Plate", "Assiette", "Piatto"),
};
const FERT = {
  "maschinell hergestellt": T("maschinell gefertigt", "machine-made", "fabriqué à la machine", "realizzato a macchina"),
  "Premium Maschinell Gefertigt": T("maschinell gefertigt (Premium-Fertigung)", "machine-made (premium production)", "fabriqué à la machine (fabrication premium)", "realizzato a macchina (produzione premium)"),
  Handgefertigt: T("von Hand gefertigt", "handmade", "fabriqué à la main", "realizzato a mano"),
};
const MAT = {
  Kristallglas: { kurz: T("aus Kristallglas", "made of crystal glass", "en cristallin", "in vetro cristallino"), merkmal: T("Kristallglas", "Crystal glass", "Cristallin", "Vetro cristallino") },
  Bleikristall: { kurz: T("aus Bleikristall", "made of lead crystal", "en cristal au plomb", "in cristallo al piombo"), merkmal: T("Bleikristall", "Lead crystal", "Cristal au plomb", "Cristallo al piombo") },
};
const KAT = {
  Rotweingläser: T("Rotweingläsern", "red wine glasses", "verres à vin rouge", "calici per vino rosso"),
  Weißweingläser: T("Weißweingläsern", "white wine glasses", "verres à vin blanc", "calici per vino bianco"),
  Weingläser: T("Weingläsern", "wine glasses", "verres à vin", "calici da vino"),
  "Champagner Weingläser": T("Champagner-Weingläsern", "champagne wine glasses", "verres à vin de champagne", "calici da champagne"),
  "Cocktail- & Bar-Gläser": T("Cocktail- und Bargläsern", "cocktail and bar glasses", "verres à cocktail et de bar", "bicchieri da cocktail e da bar"),
  Spirituosengläser: T("Spirituosengläsern", "spirits glasses", "verres à spiritueux", "bicchieri per distillati"),
  "Wasser- & Softdrinkgläser": T("Wasser- und Softdrinkgläsern", "water and soft drink glasses", "verres à eau et à soft drinks", "bicchieri per acqua e bibite"),
  "Spezial-Gläser & Sets": T("Spezialgläsern und Sets", "special glasses and sets", "verres spéciaux et coffrets", "bicchieri speciali e set"),
  "Dekanter & Karaffen": T("Dekantern und Karaffen", "decanters and carafes", "carafes à décanter et carafes", "decanter e caraffe"),
  Kaffeegläser: T("Kaffeegläsern", "coffee glasses", "verres à café", "bicchieri da caffè"),
  Biergläser: T("Biergläsern", "beer glasses", "verres à bière", "bicchieri da birra"),
  "Tischwaren & Home Accessoires": T("Tischwaren und Wohnaccessoires", "tableware and home accessories", "arts de la table et accessoires de maison", "articoli per la tavola e accessori per la casa"),
};
const FARBE = {
  "klares kristallglas": ["Klares Kristallglas", "clear crystal glass", "cristallin transparent", "vetro cristallino trasparente"],
  amethyst: ["Amethyst", "amethyst", "améthyste", "ametista"], aquamarin: ["Aquamarin", "aquamarine", "aigue-marine", "acquamarina"],
  bernstein: ["Bernstein", "amber", "ambre", "ambra"], goldrubin: ["Goldrubin", "gold ruby", "rubis doré", "rubino oro"],
  kobaltblau: ["Kobaltblau", "cobalt blue", "bleu cobalt", "blu cobalto"], "resedagrün": ["Resedagrün", "reseda green", "vert réséda", "verde reseda"],
  "smaragdgrün": ["Smaragdgrün", "emerald green", "vert émeraude", "verde smeraldo"], aqua: ["Aqua", "aqua", "aqua", "acqua"],
  reseda: ["Reseda", "reseda", "réséda", "reseda"], "black edition": ["Black Edition", "Black Edition", "Black Edition", "Black Edition"],
  schwarz: ["Schwarz", "black", "noir", "nero"], "weiß": ["Weiß", "white", "blanc", "bianco"], rot: ["Rot", "red", "rouge", "rosso"],
  mocca: ["Mocca", "mocha", "moka", "moka"], gold: ["Gold", "gold", "or", "oro"],
};
/** Farbangabe der Produktseite → 4 Sprachen (unbekannte Wörter: unverändert). */
function farbe(s) {
  const whole = FARBE[s.toLowerCase()];
  if (whole) return T(...whole);
  const parts = s.split(/\s\/\s/).map((x) => FARBE[x.trim().toLowerCase()]);
  if (parts.some((x) => !x)) return s;
  return T(...[0, 1, 2, 3].map((i) => parts.map((p) => p[i]).join(" / ")));
}
const PACK_FEST = {
  Einzelpackung: T("Einzeln", "Single", "À l'unité", "Singolo"),
  Einzelverpackung: T("Einzeln", "Single", "À l'unité", "Singolo"),
  "Vorteilsset – Kauf 4, Zahl 3": T("Vorteilsset 4 Stück (4 kaufen, 3 bezahlen)", "Value set of 4 (buy 4, pay for 3)", "Coffret avantage de 4 (4 achetés, 3 payés)", "Set convenienza da 4 (compri 4, paghi 3)"),
  Spezialset: T("Spezialset", "Special set", "Coffret spécial", "Set speciale"),
  "Karaffe mit 2 Gläsern": T("Karaffe mit 2 Gläsern", "Carafe with 2 glasses", "Carafe avec 2 verres", "Caraffa con 2 bicchieri"),
};
/** Packungsangabe → 4 Sprachen („4er-Set“, „4-teiliges Set“, „Set of 2“, „6er Set“). */
function pack(s) {
  if (PACK_FEST[s]) return PACK_FEST[s];
  const m = /^(\d+)(?:er[ -]Set|-teiliges Set)$/.exec(s) || /^Set of (\d+)$/.exec(s);
  if (m) return T(`${m[1]}er-Set`, `Set of ${m[1]}`, `Lot de ${m[1]}`, `Set da ${m[1]}`);
  return s;
}
const L = ["de", "en", "fr", "it"];
const lang = (x, l) => (typeof x === "string" ? x : x[l]);
/** Mehrere Texte (4 Sprachen oder neutral) zu einem 4-Sprachen-Text verbinden. */
const verbinde = (teile, sep = " · ") => T(...L.map((l) => teile.map((t) => lang(t, l)).join(sep)));
/** Femininum (FR/IT) für Partizipien. */
const FEM = { fr: new Set(["Karaffe", "Platte", "Teller"]), it: new Set(["Karaffe"]) };

const MERKMAL = {
  mousse: T("Mit Moussierpunkt („Perlage Driver“)", "With an effervescence point (“Perlage Driver”)", "Avec point d'effervescence (« Perlage Driver »)", "Con punto di effervescenza (“Perlage Driver”)"),
  spuel: T("Laut Hersteller spülmaschinenfest", "Dishwasher-safe according to the manufacturer", "Compatible lave-vaisselle selon le fabricant", "Lavabile in lavastoviglie secondo il produttore"),
  hand: T("Laut Hersteller spülmaschinenfest; zur Pflege empfiehlt er die Reinigung von Hand", "Dishwasher-safe according to the manufacturer, who recommends washing by hand for care", "Compatible lave-vaisselle selon le fabricant, qui recommande toutefois un lavage à la main", "Lavabile in lavastoviglie secondo il produttore, che per la cura consiglia il lavaggio a mano"),
  handstueck: T("Von Hand gefertigt: kleine Abweichungen und feine Bläschen sind laut Hersteller Teil der Fertigung", "Handmade: according to the manufacturer, slight variations and fine bubbles are part of the process", "Fait main : selon le fabricant, de légères variations et de fines bulles font partie de la fabrication", "Fatto a mano: secondo il produttore, lievi differenze e piccole bolle fanno parte della lavorazione"),
  liter1: T("Fassungsvermögen 1 Liter", "Capacity 1 litre", "Contenance 1 litre", "Capacità 1 litro"),
  set2t1d: T("Inhalt: 2 Whisky-Tumbler und 1 Dekanter", "Contents: 2 whisky tumblers and 1 decanter", "Contenu : 2 gobelets à whisky et 1 carafe", "Contenuto: 2 tumbler da whisky e 1 decanter"),
  set1k2g: T("Inhalt: 1 Karaffe und 2 Gläser", "Contents: 1 carafe and 2 glasses", "Contenu : 1 carafe et 2 verres", "Contenuto: 1 caraffa e 2 bicchieri"),
};

/** Kurztext (eigene Worte, nur Fakten der Produktseite). */
function kurz(r) {
  if (r.kurz) return T(r.kurz.de, r.kurz.en, r.kurz.fr, r.kurz.it);
  const typ = TYP[r.typ] || TYP.Glas;
  const fert = FERT[r.fert];
  const mat = MAT[r.mat] ? MAT[r.mat].kurz : null;
  const ffr = FEM.fr.has(r.typ), fit = FEM.it.has(r.typ);
  const fertL = (l) => (!fert ? "" : `, ${l === "fr" && ffr ? fert.fr.replace(/é(?=\s|$)/, "ée") : l === "it" && fit ? fert.it.replace(/o(?=\s|$)/, "a") : fert[l]}`);
  const s = r.serie;
  const s1 = T(
    `${typ.de}${mat ? ` ${mat.de}` : ""}${s ? ` der Kollektion ${s}` : ""}${fertL("de")}.`,
    `${typ.en}${mat ? ` ${mat.en}` : ""}${s ? ` from the ${s} collection` : ""}${fertL("en")}.`,
    `${typ.fr}${mat ? ` ${mat.fr}` : ""}${s ? ` de la collection ${s}` : ""}${fertL("fr")}.`,
    `${typ.it}${mat ? ` ${mat.it}` : ""}${s ? ` della collezione ${s}` : ""}${fertL("it")}.`
  );
  const k = KAT[r.cat];
  if (!k) return s1;
  const s2 = T(`Im Sortiment des Herstellers bei den ${k.de} geführt.`, `Listed by the manufacturer among its ${k.en}.`, `${ffr ? "Classée" : "Classé"} par le fabricant parmi ses ${k.fr}.`, `${fit ? "Classificata" : "Classificato"} dal produttore tra i suoi ${k.it}.`);
  return T(...L.map((l) => `${s1[l]} ${s2[l]}`));
}

function merkmale(r) {
  const out = [];
  const fert = FERT[r.fert];
  const m = MAT[r.mat]?.merkmal;
  if (m) out.push(fert ? T(`${m.de}, ${fert.de}`, `${m.en}, ${fert.en}`, `${m.fr}, ${fert.fr}`, `${m.it}, ${fert.it}`) : m);
  if (r.packs?.length) {
    const p = verbinde([...new Set(r.packs.map((x) => JSON.stringify(pack(x))))].map((x) => JSON.parse(x)), ", ");
    out.push(T(`Packungen: ${p.de}`, `Packs: ${p.en}`, `Conditionnements : ${p.fr}`, `Confezioni: ${p.it}`));
  }
  if (r.farben?.length) {
    const f = verbinde(r.farben.map(farbe), ", ");
    const n = r.farben.length > 1;
    out.push(T(`Farbe${n ? "n" : ""}: ${f.de}`, `Colour${n ? "s" : ""}: ${f.en}`, `Couleur${n ? "s" : ""} : ${f.fr}`, `Color${n ? "i" : "e"}: ${f.it}`));
  }
  for (const f of r.f || []) out.push(MERKMAL[f]);
  return Object.freeze(out);
}

const GRUPPE = {
  packung: T("Packung", "Pack", "Conditionnement", "Confezione"),
  farbe: T("Farbe", "Colour", "Couleur", "Colore"),
  ausfuehrung: T("Ausführung", "Version", "Version", "Versione"),
};
// Zubehör aus dem Riedel-Sortiment desselben Shops (Slugs in riedel.js)
const ZUBEHOER_HINWEIS = {
  tuch: T("Zum Polieren von Gläsern und Karaffen", "For polishing glasses and carafes", "Pour polir verres et carafes", "Per lucidare bicchieri e caraffe"),
  perlen: T("Zum Reinigen von Karaffe und Dekanter", "For cleaning carafes and decanters", "Pour nettoyer carafes et carafes à décanter", "Per pulire caraffe e decanter"),
  tasche: T("Zum Transport von bis zu fünf Stielgläsern", "For carrying up to five stemmed glasses", "Pour transporter jusqu'à cinq verres à pied", "Per trasportare fino a cinque calici"),
};
const idOf = (t) =>
  String(typeof t === "string" ? t : t.de)
    .toLowerCase()
    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "option";
const bild = (b, typ, alt) => Object.freeze({ src: `/Images/Wellness/produkte/${MARKE_SLUG}/${b[0]}`, width: b[1], height: b[2], alt, quelleUrl: b[3], abgerufen: STAND, typ });

/** Produkt aus einer Datenzeile (Werte von der jeweiligen Produktseite des AT-Shops). */
function produkt(r) {
  const name = r.n;
  // Name in Alt-Texten (r.an: ohne Namensteile, die die Wortregeln sperren, z. B. „Perfect“)
  const an = `${MARKE_NAME} ${r.an || name}`;
  const vs = r.v || [];
  // Jede Kaufoption ist eine Variante (auch bei nur einer: Name = Packung), damit
  // Artikelnummer (sku, laut Shop „SKU“) und zerbrechlich Platz haben.
  const varianten = vs.map(([o, betrag, sku]) => {
    const teile = vs.length === 1 ? [o.p ? pack(o.p) : o.x, o.c && farbe(o.c)].filter(Boolean) : [o.x, o.p && pack(o.p), o.c && farbe(o.c)].filter(Boolean);
    const n = teile.length === 1 ? teile[0] : verbinde(teile);
    return Object.freeze({ name: n, betrag, ...(sku ? { sku } : {}), zerbrechlich: true });
  });
  const preis = varianten.length ? Object.freeze({ art: "verkaufspreis", varianten: Object.freeze(varianten), stand: STAND, quelle: r.url }) : undefined;
  // Ausführungen (Konfigurator): gleiche Namen wie preis.varianten, Code = SKU
  let ausfuehrungen;
  if (varianten.length > 1) {
    const ids = new Set();
    let std = false;
    const optionen = varianten.map((v) => {
      let id = idOf(v.name);
      for (let i = 2; ids.has(id); i++) id = `${idOf(v.name)}-${i}`;
      ids.add(id);
      const standard = !std && v.sku != null && v.sku === r.std;
      if (standard) std = true;
      return Object.freeze({ id, name: v.name, ...(v.sku ? { code: v.sku } : {}), betrag: v.betrag, ...(standard ? { standard: true } : {}) });
    });
    ausfuehrungen = Object.freeze([Object.freeze({ gruppe: GRUPPE[r.vg] || GRUPPE.ausfuehrung, optionen: Object.freeze(optionen) })]);
  }
  const masse = [r.h && mass("hoehe", r.h), r.d && mass("durchmesser", r.d)].filter(Boolean);
  const bilder = [
    ...(r.img ? [bild(r.img, "freisteller", T(`${an} – Produktfoto des Herstellers`, `${an} – manufacturer's product photo`, `${an} – photo produit du fabricant`, `${an} – foto prodotto del produttore`))] : []),
    ...(r.amb || []).map((b) =>
      b[4] === "freisteller"
        ? bild(b, "freisteller", T(`${an} – weiteres Produktfoto des Herstellers vor hellem Hintergrund`, `${an} – further manufacturer product photo on a light background`, `${an} – autre photo produit du fabricant sur fond clair`, `${an} – altra foto prodotto del produttore su sfondo chiaro`))
        : bild(b, "ambiente", T(`${an} – Stimmungsbild des Herstellers mit dem Produkt im Einsatz`, `${an} – manufacturer's lifestyle photo showing the product in use`, `${an} – photo d'ambiance du fabricant montrant le produit en situation`, `${an} – foto d'ambiente del produttore con il prodotto in uso`))
    ),
  ];
  const zubehoer = (r.zub || []).map(([slug, h]) => Object.freeze({ slug, hinweis: ZUBEHOER_HINWEIS[h] }));
  return Object.freeze({
    slug: `${MARKE_SLUG}-${r.s}`,
    marke: MARKE_SLUG,
    bereich: "accessoires",
    kategorie: r.k,
    name,
    ...(r.serie ? { serie: r.serie } : {}),
    kurz: kurz(r),
    merkmale: merkmale(r),
    ...(masse.length ? { masse: Object.freeze(masse) } : {}),
    bilder: Object.freeze(bilder),
    herstellerUrl: r.url,
    quellen: Object.freeze([...new Set([r.url, ...(r.q || [])])]),
    stand: STAND,
    ...(preis ? { preis } : {}),
    ...(ausfuehrungen ? { ausfuehrungen } : {}),
    ...(zubehoer.length ? { zubehoer: Object.freeze(zubehoer) } : {}),
  });
}

/** Szenen („Ganze Räume ansehen“): Stimmungsbilder der jeweiligen Produktseite, gezeigtes Produkt = Produkt dieser Seite. */
const lookBild = (file, width, height, alt, quelleUrl) => Object.freeze({ src: `/Images/Wellness/produkte/nachtmann/${file}`, width, height, alt, quelleUrl, abgerufen: STAND, typ: "ambiente" });
